DECLARE @u1 NVARCHAR(450);
DECLARE @u2 NVARCHAR(450);
DECLARE @u3 NVARCHAR(450);
SELECT TOP 1 @u1 = Id FROM AspNetUsers;
SELECT TOP 1 @u2 = Id FROM AspNetUsers WHERE Id != @u1;
SELECT TOP 1 @u3 = Id FROM AspNetUsers WHERE Id != @u1 AND Id != @u2;
IF @u2 IS NULL SET @u2 = @u1;
IF @u3 IS NULL SET @u3 = @u1;

